parameters.text:
=Email reçu sur la boîte support NovaDesk.
De : {{ $json.from }}
Objet : {{ $json.subject }}
Date : {{ $json.date }}

{{ $json.textPlain || $json.textHtml }}

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "type": {
      "type": "string",
      "enum": ["Bug", "Tâche", "none"],
      "description": "Bug pour un défaut, Tâche pour une idée d'amélioration, none si aucun ticket n'est nécessaire"
    },
    "product": {
      "type": "string",
      "description": "Produit concerné, par exemple NovaCRM ou NovaPay"
    },
    "summary": {
      "type": "string",
      "description": "Résumé court du problème ou de l'idée, sans le nom du produit"
    },
    "priority": {
      "type": "string",
      "enum": ["Highest", "High", "Medium", "Low", "Lowest"],
      "description": "Priorité Jira"
    },
    "label": {
      "type": "string",
      "enum": ["back", "front"],
      "description": "back pour le serveur et les données, front pour l'interface"
    }
  },
  "required": ["type", "product", "summary", "priority", "label"],
  "additionalProperties": false
}

assignments.value:
